<template><PageShell title="工资统计" description="生成月度工资草稿，查看计算快照，增加正负调整，确认后锁定源记录。" :show-employee="false" @refresh="load"><template #actions><el-button type="primary" :loading="store.saving" @click="generate">生成/刷新草稿</el-button></template>
  <el-empty v-if="!store.payroll" description="当月尚未生成工资草稿"/><template v-else><div class="payroll-summary"><div><span>工资状态</span><el-tag :type="store.payroll.status==='CONFIRMED'?'success':'warning'">{{store.payroll.status==='CONFIRMED'?'已确认':'草稿'}}</el-tag></div><div><span>应发合计</span><strong>¥{{store.payroll.totalAmount.toFixed(2)}}</strong></div><div><span>阻断问题</span><strong>{{store.payroll.issueCount}}</strong></div><div class="summary-actions"><el-button v-if="store.payroll.status==='DRAFT'" type="success" :disabled="store.payroll.issueCount>0" @click="confirm">确认工资并锁定</el-button><el-button v-else type="warning" @click="reopen">撤销确认</el-button><el-button data-testid="export-payroll-summary" @click="exportPlaceholder">导出全员汇总 PNG</el-button></div></div>
  <el-alert v-for="issue in store.payroll.issues" :key="issue" :title="issue" type="warning" :closable="false" show-icon class="issue"/>
  <el-table :data="store.payroll.items" empty-text="暂无工资明细"><el-table-column label="员工" width="110"><template #default="{row}">{{row.employee.name}}</template></el-table-column><el-table-column label="基本工资"><template #default="{row}">¥{{row.calculationSnapshot.baseSalary.toFixed(2)}}</template></el-table-column><el-table-column label="加班费"><template #default="{row}">¥{{row.calculationSnapshot.overtimePay.toFixed(2)}}</template></el-table-column><el-table-column label="提成+奖金"><template #default="{row}">¥{{(row.calculationSnapshot.commissionAmount+row.calculationSnapshot.bonusAmount).toFixed(2)}}</template></el-table-column><el-table-column label="人工调整"><template #default="{row}"><div v-for="adjustment in row.adjustments" :key="adjustment.id">{{adjustment.amount>0?'+':''}}{{adjustment.amount.toFixed(2)}} · {{adjustment.reason}} <el-button v-if="store.payroll?.status==='DRAFT'" link type="danger" @click="removeAdjustment(adjustment.id)">删除</el-button></div><el-button v-if="store.payroll?.status==='DRAFT'" link type="primary" @click="openAdjustment(row.id)">增加调整</el-button></template></el-table-column><el-table-column label="应发工资"><template #default="{row}"><span class="money">¥{{row.payableAmount.toFixed(2)}}</span></template></el-table-column><el-table-column label="操作" width="145"><template #default="{row}"><el-button data-testid="export-payroll-slip" link type="primary" @click="exportPlaceholder">导出工资条 PNG</el-button><el-popover v-if="row.issues.length" trigger="hover" :content="row.issues.join('；')"><template #reference><el-tag type="warning">异常 {{row.issues.length}}</el-tag></template></el-popover></template></el-table-column></el-table></template>
</PageShell><el-dialog v-model="adjustmentVisible" title="增加工资调整" width="480px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="调整金额（可为负数）" required><el-input-number v-model="adjustment.amount"/></el-form-item><el-form-item label="调整原因" required><el-input v-model="adjustment.reason"/></el-form-item></el-form><template #footer><el-button @click="adjustmentVisible=false">取消</el-button><el-button type="primary" @click="saveAdjustment">保存</el-button></template></el-dialog></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import PageShell from'./EmployeeAttendancePageShell.vue';import{useEmployeeAttendanceStore}from'@/stores/employeeAttendance';import*as api from'@/api/employeeAttendance';const store=useEmployeeAttendanceStore(),adjustmentVisible=ref(false),adjustmentItemId=ref(''),formError=ref(''),adjustment=reactive({amount:0,reason:''});async function load(){await store.loadPayroll().catch(()=>undefined)}async function generate(){await store.run(()=>api.generatePayroll(store.month),true).then(row=>{store.payroll=row;ElMessage.success('工资草稿已生成')}).catch(()=>undefined)}function openAdjustment(id:string){adjustmentItemId.value=id;Object.assign(adjustment,{amount:0,reason:''});formError.value='';adjustmentVisible.value=true}async function saveAdjustment(){try{await api.createPayrollAdjustment(adjustmentItemId.value,{...adjustment});adjustmentVisible.value=false;await load()}catch(error){formError.value=error instanceof Error?error.message:'保存失败'}}async function removeAdjustment(id:string){await api.deletePayrollAdjustment(id);await load()}async function confirm(){if(!store.payroll)return;try{await ElMessageBox.confirm('确认后当月考勤、请假、提成和奖金将被锁定。','确认工资',{type:'warning'});store.payroll=await api.confirmPayroll(store.payroll.id)}catch{/* cancel */}}async function reopen(){if(!store.payroll)return;try{const{value}=await ElMessageBox.prompt('撤销后可重新修改当月数据，请填写原因。','撤销确认',{inputPattern:/\S+/,inputErrorMessage:'原因必填'});store.payroll=await api.reopenPayroll(store.payroll.id,value)}catch{/* cancel */}}function exportPlaceholder(){ElMessage.info('PNG 导出接口已预留，将在导出模块中启用')}onMounted(load);
</script><style scoped>.payroll-summary{display:flex;align-items:center;gap:28px;padding:14px;background:#f8fbff;border:1px solid #dbe5f0;border-radius:7px;margin-bottom:12px}.payroll-summary span{display:block;color:#64748b;font-size:12px;margin-bottom:6px}.payroll-summary strong{font-size:18px}.summary-actions{margin-left:auto;display:flex;gap:8px}.issue{margin:8px 0}</style>
